UPDATE users SET waitlist_status = 'pending' WHERE waitlist_status IS NULL;
UPDATE users SET referral_code = CONCAT(LOWER(SUBSTRING(MD5(RAND()), 1, 12))) WHERE referral_code IS NULL;
UPDATE users u JOIN (SELECT id, ROW_NUMBER() OVER (ORDER BY created_at ASC) AS pos FROM users) ranked ON u.id = ranked.id SET u.waitlist_position = ranked.pos WHERE u.waitlist_position IS NULL;

